-- Installed ONLY by the owned-fixture guard. Never a Prisma/application migration.
CREATE SCHEMA approval_rehearsal;
CREATE TABLE approval_rehearsal.installation (run_id text PRIMARY KEY);
CREATE TABLE approval_rehearsal.policy (id int PRIMARY KEY CHECK(id=1), version text NOT NULL);
CREATE TABLE approval_rehearsal.human (id uuid PRIMARY KEY, verified boolean NOT NULL, epoch bigint NOT NULL CHECK(epoch>0));
CREATE TABLE approval_rehearsal.account (id uuid PRIMARY KEY, human_id uuid NOT NULL REFERENCES approval_rehearsal.human);
CREATE TABLE approval_rehearsal.session_record (id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES approval_rehearsal.account, token_hash text UNIQUE NOT NULL, epoch bigint NOT NULL, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE approval_rehearsal.capability_grant (id uuid PRIMARY KEY, human_id uuid NOT NULL REFERENCES approval_rehearsal.human, resource_id uuid NOT NULL, action text NOT NULL CHECK(action IN ('fixture.propose','fixture.approve','fixture.execute')), policy_version text NOT NULL, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE approval_rehearsal.assurance (id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES approval_rehearsal.session_record, human_id uuid NOT NULL REFERENCES approval_rehearsal.human, epoch bigint NOT NULL, kind text NOT NULL CHECK(kind IN ('TEST_VERIFIED','PENDING')), verified_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE TABLE approval_rehearsal.resource (id uuid PRIMARY KEY, value int NOT NULL DEFAULT 0, version bigint NOT NULL DEFAULT 1, evidence_version bigint NOT NULL DEFAULT 1, policy_version text NOT NULL, lifecycle text NOT NULL DEFAULT 'READY' CHECK(lifecycle IN ('READY','CONSUMED')), conflicts uuid[] NOT NULL DEFAULT '{}');
CREATE TABLE approval_rehearsal.payload (id uuid PRIMARY KEY, canonical text NOT NULL, hash text NOT NULL, UNIQUE(id,hash), CHECK(hash=encode(sha256(convert_to(canonical,'UTF8')),'hex')), CHECK(canonical=(canonical::jsonb)::text));
CREATE TABLE approval_rehearsal.proposal (id uuid PRIMARY KEY, requester_id uuid NOT NULL REFERENCES approval_rehearsal.human, requester_session_id uuid NOT NULL REFERENCES approval_rehearsal.session_record, action text NOT NULL CHECK(action='synthetic.counter.advance'), current_revision int NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL);
CREATE TABLE approval_rehearsal.proposal_revision (proposal_id uuid NOT NULL REFERENCES approval_rehearsal.proposal, revision int NOT NULL, payload_id uuid NOT NULL, payload_hash text NOT NULL, resource_id uuid NOT NULL REFERENCES approval_rehearsal.resource, resource_version bigint NOT NULL, evidence_version bigint NOT NULL, policy_version text NOT NULL, requester_epoch bigint NOT NULL, PRIMARY KEY(proposal_id,revision), UNIQUE(proposal_id,revision,payload_hash), FOREIGN KEY(payload_id,payload_hash) REFERENCES approval_rehearsal.payload(id,hash));
CREATE TABLE approval_rehearsal.decision (id uuid PRIMARY KEY, proposal_id uuid NOT NULL, revision int NOT NULL, payload_hash text NOT NULL, approver_id uuid NOT NULL REFERENCES approval_rehearsal.human, approver_session_id uuid NOT NULL REFERENCES approval_rehearsal.session_record, approver_epoch bigint NOT NULL, expires_at timestamptz NOT NULL, ruling text NOT NULL CHECK(ruling='HYPOTHETICAL_INDEPENDENT'), UNIQUE(proposal_id,revision), FOREIGN KEY(proposal_id,revision,payload_hash) REFERENCES approval_rehearsal.proposal_revision(proposal_id,revision,payload_hash));
CREATE TABLE approval_rehearsal.audit_event (id uuid PRIMARY KEY, attempt_id uuid NOT NULL, proposal_id uuid, kind text NOT NULL CHECK(kind IN ('REHEARSAL_EFFECT_COMMITTED','REHEARSAL_DENIED','REHEARSAL_FAILED')), payload_hash text, requester_id uuid, approver_id uuid, executor_id uuid, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE approval_rehearsal.receipt (id uuid PRIMARY KEY, proposal_id uuid NOT NULL, revision int NOT NULL, decision_id uuid UNIQUE NOT NULL REFERENCES approval_rehearsal.decision, payload_hash text NOT NULL, resource_id uuid NOT NULL REFERENCES approval_rehearsal.resource, requester_id uuid NOT NULL, approver_id uuid NOT NULL, executor_id uuid NOT NULL, before_version bigint NOT NULL, after_version bigint NOT NULL, before_value int NOT NULL, after_value int NOT NULL, evidence_version bigint NOT NULL, policy_version text NOT NULL, requester_epoch bigint NOT NULL, approver_epoch bigint NOT NULL, executor_epoch bigint NOT NULL, audit_id uuid UNIQUE NOT NULL REFERENCES approval_rehearsal.audit_event, outcome text NOT NULL CHECK(outcome='REHEARSAL_COMMITTED'), UNIQUE(proposal_id,revision), FOREIGN KEY(proposal_id,revision,payload_hash) REFERENCES approval_rehearsal.proposal_revision(proposal_id,revision,payload_hash), CHECK(after_value=before_value+1 AND after_version=before_version+1));
CREATE FUNCTION approval_rehearsal.immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Rehearsal history immutable'; END $$;
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['payload','proposal_revision','decision','receipt','audit_event'] LOOP EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON approval_rehearsal.%I FOR EACH ROW EXECUTE FUNCTION approval_rehearsal.immutable()',tbl); END LOOP; END $$;

CREATE FUNCTION approval_rehearsal.proposal_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,approval_rehearsal AS $$
BEGIN
 IF TG_OP='DELETE' OR (to_jsonb(NEW)-'current_revision') IS DISTINCT FROM (to_jsonb(OLD)-'current_revision') OR NEW.current_revision<>OLD.current_revision+1 OR NOT EXISTS(SELECT 1 FROM approval_rehearsal.proposal_revision WHERE proposal_id=OLD.id AND revision=NEW.current_revision) THEN RAISE EXCEPTION 'Rehearsal proposal immutable except new revision'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER proposal_immutable BEFORE UPDATE OR DELETE ON approval_rehearsal.proposal FOR EACH ROW EXECUTE FUNCTION approval_rehearsal.proposal_immutable();
